  ('openai_azure_openai', 'OpenAI / Azure OpenAI', 'ai', 'Verify enterprise zero-retention (ZDR), enforce allowed model versions, track API spend/usage.', 'Reads Zero-data retention opt-out status, active model versions, and API key metadata via API.', 'Add Read-only Admin API Key or Azure Service Principal with Cognitive Services Reader role in Vanta.', 'Map ZDR status and API keys to EU AI Act Transparency, ISO 42001 A.8.2, and NIST Manage 1.1 controls.', 'Vanta Help Center -> AI Systems -> OpenAI', 3, 'catalogued'),
  ('aws_bedrock', 'AWS Bedrock', 'ai', 'Ensure centralized model access, guardrail enforcement, and invocation logging.', 'Pulls model invocation logs, guardrail configs, and IAM policies.', 'Connect via AWS IAM Cross-Account STS Role with bedrock:Get* and bedrock:List* permissions.', 'Map Bedrock logging and guardrails to ISO 42001 A.7.2, NIST Govern 1.2, and SOC 2 CC6.1.', 'Vanta Help Center -> AI Systems -> AWS Bedrock', 3, 'catalogued'),
  ('google_cloud_vertex_ai', 'Google Cloud Vertex AI', 'ai', 'Audit ML model deployments, pipeline safety filters, and model endpoint metadata.', 'Fetches ACLs, safety attribute configs, and model registry history via API.', 'Link via GCP Service Account with roles/aiplatform.viewer and roles/logging.viewer.', 'Map deployment approvals and safety filters to ISO 42001 A.8.4 and NIST Map 1.5.', 'Vanta Help Center -> AI Systems -> Vertex AI', 3, 'catalogued'),
  ('anthropic_claude_api', 'Anthropic (Claude API)', 'ai', 'Track commercial LLM usage, enterprise data boundaries, and API seat provisioning.', 'Pulls workspace user lists, active keys, and commercial tier settings.', 'Add Anthropic Organization Admin API Token (Read-only) in Vanta.', 'Map active keys and seat configs to ISO 42001 A.6.2 and NIST Measure 2.5.', 'Vanta Help Center -> AI Systems -> Anthropic', 2, 'catalogued'),
  ('langsmith_langfuse', 'LangSmith / Langfuse', 'ai', 'Continuous tracing of prompt inputs, outputs, hallucination scores, and safety evals.', 'Ingests toxicity/hallucination scores, prompt changes, and feedback logs via webhook/API.', 'Provide API Service Key or configure automated webhook export to Vanta ingestion queue.', 'Map hallucination rates and evals to EU AI Act Human Oversight and NIST Measure 2.6.', 'Vanta Help Center -> AI Observability', 3, 'catalogued'),
