-- 20260825000002_seed_integration_catalog.sql
--
-- Seeds integration_catalog from the "Continuous GRC & AI Integrations
-- Master" workbook supplied by the product owner (2026-08-25) — 225 rows,
-- 16 duplicate product names folded to one row each (first occurrence wins;
-- e.g. GitHub Actions appears under both cloud and CI/CD in the source).
-- Text columns carry the sheet's own wording, trimmed; nothing is invented.
-- tier/adapter_status are Sentinel's rollout state, not sheet data:
-- tier 1 = adapter shipped or next to ship, 2 = planned, 3 = catalogued.
--
-- Idempotent: ON CONFLICT (slug) refreshes catalogue text but never
-- downgrades tier/adapter_status maintained by later migrations.
-- Applied live to Supabase project vhparvughsygyknblkzt on 2026-08-25.

on conflict (slug) do update set
  name = excluded.name,
  category = excluded.category,
  why_needed = excluded.why_needed,
  evidence_pull = excluded.evidence_pull,
  connect_steps = excluded.connect_steps,
  evidence_mapping = excluded.evidence_mapping,
  docs_hint = excluded.docs_hint,
  updated_at = now();
